// ─── File: DomainFactDemo.java ───
// Runnable demo: raw-changelog anti-pattern vs deliberate domain-fact publishing.

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class DomainFactDemo {

    private static final Logger log = Logger.getLogger("domainfact");

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ConsumerView consumer = new ConsumerView();

        log.info("===== RAW CHANGELOG (anti-pattern): publish every row change =====");
        RawChangelogPublisher raw = new RawChangelogPublisher(consumer);
        TransferStateMachine sm1 = new TransferStateMachine("T-123", "SAV2001", "BENEF-77",
                new BigDecimal("50000"), raw);
        sm1.run();                         // emits a public event per mutation
        consumer.report("RAW_CHANGELOG");

        consumer.reset();

        log.info("===== DOMAIN FACT (correct): one meaningful business event =====");
        DomainFactPublisher fact = new DomainFactPublisher(consumer);
        TransferStateMachine sm2 = new TransferStateMachine("T-124", "SAV2001", "BENEF-77",
                new BigDecimal("50000"), fact);
        sm2.run();                         // emits exactly one TransferCompleted
        consumer.report("DOMAIN_FACT");
    }
}

// ─── publish/Publisher.java (interface via abstract behavior) ───
interface Publisher {
    void onRowChange(String table, String column, String value);   // internal mutation
    void onTransferCompleted(String transferId, String accountId, String beneficiary, BigDecimal amount);
}

// ─── statemachine/TransferStateMachine.java — drives internal mutations ───
class TransferStateMachine {
    private static final Logger log = Logger.getLogger("domainfact");
    private final String id, account, beneficiary; private final BigDecimal amount;
    private final Publisher publisher;
    TransferStateMachine(String id, String account, String beneficiary, BigDecimal amount, Publisher publisher) {
        this.id = id; this.account = account; this.beneficiary = beneficiary; this.amount = amount; this.publisher = publisher;
    }
    void run() {
        // Several INTERNAL row changes for ONE business operation.
        publisher.onRowChange("transfer", "status", "DRAFT");
        publisher.onRowChange("transfer", "status", "VALIDATING");
        publisher.onRowChange("transfer", "status", "RISK_CHECKED");
        publisher.onRowChange("internal_ledger", "entry", id + "-leg1");  // internal table
        publisher.onRowChange("transfer", "status", "COMPLETED");
        // The ONE meaningful business fact:
        publisher.onTransferCompleted(id, account, beneficiary, amount);
    }
}

// ─── publish/RawChangelogPublisher.java — ANTI-PATTERN ───
class RawChangelogPublisher implements Publisher {
    private static final Logger log = Logger.getLogger("domainfact");
    private final ConsumerView consumer;
    RawChangelogPublisher(ConsumerView consumer) { this.consumer = consumer; }
    public void onRowChange(String table, String column, String value) {
        // Publishing EVERY mutation as a public event leaks internals.
        log.warning(() -> "[RAW] public event: " + table + "." + column + "=" + value + " (leaks internals)");
        consumer.receive(new RowChangeEvent(table, column, value));
    }
    public void onTransferCompleted(String id, String acct, String ben, BigDecimal amt) {
        // In the anti-pattern the business meaning is drowned among row events.
        consumer.receive(new RowChangeEvent("transfer", "status", "COMPLETED"));
    }
}

// ─── publish/DomainFactPublisher.java — CORRECT ───
class DomainFactPublisher implements Publisher {
    private static final Logger log = Logger.getLogger("domainfact");
    private final ConsumerView consumer;
    DomainFactPublisher(ConsumerView consumer) { this.consumer = consumer; }
    public void onRowChange(String table, String column, String value) {
        // Internal mutations stay PRIVATE — not published.
        log.fine(() -> "[FACT] internal mutation kept private: " + table + "." + column + "=" + value);
    }
    public void onTransferCompleted(String id, String acct, String ben, BigDecimal amt) {
        // Publish exactly one deliberate, versioned business fact.
        log.info(() -> "[FACT] public event: TransferCompleted v1 { " + id + ", " + acct + ", " + ben + ", Rs." + amt + " }");
        consumer.receive(new TransferCompletedEvent(id, acct, ben, amt));
    }
}

// ─── events/RowChangeEvent.java ───
class RowChangeEvent {
    final String table, column, value;
    RowChangeEvent(String table, String column, String value) { this.table = table; this.column = column; this.value = value; }
}

// ─── events/TransferCompletedEvent.java — versioned contract ───
class TransferCompletedEvent {
    final String transferId, accountId, beneficiary; final BigDecimal amount; final int schemaVersion = 1;
    TransferCompletedEvent(String transferId, String accountId, String beneficiary, BigDecimal amount) {
        this.transferId = transferId; this.accountId = accountId; this.beneficiary = beneficiary; this.amount = amount;
    }
}

// ─── consumer/ConsumerView.java ───
class ConsumerView {
    private static final Logger log = Logger.getLogger("domainfact");
    private int rowEvents = 0, factEvents = 0; private final Set<String> leakedInternals = new LinkedHashSet<>();
    void receive(RowChangeEvent e) { rowEvents++;
        if (!e.table.equals("transfer") || !e.column.equals("status") || !e.value.equals("COMPLETED"))
            leakedInternals.add(e.table + "." + e.value); }
    void receive(TransferCompletedEvent e) { factEvents++; }
    void report(String mode) {
        log.info(() -> "[CONSUMER " + mode + "] rowEvents=" + rowEvents + " factEvents=" + factEvents
                + " leakedInternals=" + leakedInternals);
    }
    void reset() { rowEvents = 0; factEvents = 0; leakedInternals.clear(); }
}

// ─── BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tH:%1$tM:%1$tS %2$-7s %3$s%n",
                new Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
